-- ==============================================================================
-- STEP 1 FEATURE ENGINEERING OF THE POOLED CROSS-SECTIONAL MODEL
-- Generated by docs/generate_sql.py from src/processing/features.py and
-- config/settings.yaml. Reference documentation: the pipeline computes the same
-- columns in pandas.
--
-- Input: daily_prices(date, ticker, close, volume), one row per stock and trading day
-- with an adjusted close (the stock's own trading days).
-- Settings: horizon_days = 126, threshold = 0.1,
-- step1_ffill_limit_days = 5, step1_min_price_eur = 1.0,
-- step1_features = ret_21, ret_63, ret_126, mom_12_1, dist_sma50, dist_sma200, vol_21, vol_126, log_traded_value, drawdown_252.
-- ==============================================================================

WITH own_days AS (
    -- 1. The stock's own trading days; a missing volume counts as 0
    SELECT
        date,
        ticker,
        close,
        COALESCE(volume, 0) AS volume,
        close / NULLIF(LAG(close, 1) OVER (PARTITION BY ticker ORDER BY date), 0) - 1 AS daily_return
    FROM daily_prices
    WHERE close IS NOT NULL
),

stock_features AS (
    -- 2. Features, forward return and label end date per stock. Every window counts
    --    the stock's own trading days and is NULL until it is complete.
    SELECT
        date,
        ticker,
        close AS price,
        close / NULLIF(LAG(close, 21) OVER (PARTITION BY ticker ORDER BY date), 0) - 1 AS ret_21,
        close / NULLIF(LAG(close, 63) OVER (PARTITION BY ticker ORDER BY date), 0) - 1 AS ret_63,
        close / NULLIF(LAG(close, 126) OVER (PARTITION BY ticker ORDER BY date), 0) - 1 AS ret_126,
        LAG(close, 21) OVER (PARTITION BY ticker ORDER BY date) / NULLIF(LAG(close, 252) OVER (PARTITION BY ticker ORDER BY date), 0) - 1 AS mom_12_1,
        CASE WHEN COUNT(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 49 PRECEDING AND CURRENT ROW) = 50 THEN close / NULLIF(AVG(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 49 PRECEDING AND CURRENT ROW), 0) - 1 END AS dist_sma50,
        CASE WHEN COUNT(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 199 PRECEDING AND CURRENT ROW) = 200 THEN close / NULLIF(AVG(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 199 PRECEDING AND CURRENT ROW), 0) - 1 END AS dist_sma200,
        CASE WHEN COUNT(daily_return) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 20 PRECEDING AND CURRENT ROW) = 21 THEN STDDEV_SAMP(daily_return) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 20 PRECEDING AND CURRENT ROW) END AS vol_21,
        CASE WHEN COUNT(daily_return) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 125 PRECEDING AND CURRENT ROW) = 126 THEN STDDEV_SAMP(daily_return) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 125 PRECEDING AND CURRENT ROW) END AS vol_126,
        CASE WHEN COUNT(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 125 PRECEDING AND CURRENT ROW) = 126 THEN LN(1 + AVG(close * volume) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 125 PRECEDING AND CURRENT ROW)) END AS log_traded_value,
        CASE WHEN COUNT(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW) = 252 THEN close / NULLIF(MAX(close) OVER (PARTITION BY ticker ORDER BY date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0) - 1 END AS drawdown_252,
        -- Forward return over horizon_days = 126 own trading days and its end date
        LEAD(close, 126) OVER (PARTITION BY ticker ORDER BY date) / NULLIF(close, 0) - 1 AS fwd,
        LEAD(date, 126) OVER (PARTITION BY ticker ORDER BY date) AS label_end
    FROM own_days
),

calendar AS (
    -- 3. Union calendar: every date on which at least one stock traded
    SELECT date, ROW_NUMBER() OVER (ORDER BY date) AS day_no
    FROM (SELECT DISTINCT date FROM own_days) AS dates
),

carried AS (
    -- 4. A day without a trade carries the stock's last own trading day for at most
    --    step1_ffill_limit_days = 5 days of the union calendar; the latest own row wins
    SELECT
        c.date,
        f.ticker,
        f.date AS last_trade,
        f.price,
        f.ret_21,
        f.ret_63,
        f.ret_126,
        f.mom_12_1,
        f.dist_sma50,
        f.dist_sma200,
        f.vol_21,
        f.vol_126,
        f.log_traded_value,
        f.drawdown_252,
        f.fwd,
        f.label_end,
        ROW_NUMBER() OVER (PARTITION BY c.date, f.ticker ORDER BY f.date DESC) AS recency
    FROM calendar AS c
    JOIN calendar AS own ON own.day_no BETWEEN c.day_no - 5 AND c.day_no
    JOIN stock_features AS f ON f.date = own.date
),

eligible AS (
    -- 5. Eligibility: every feature present, a positive traded value and a price above
    --    step1_min_price_eur = 1.0
    SELECT *
    FROM carried
    WHERE recency = 1
      AND ret_21 IS NOT NULL
      AND ret_63 IS NOT NULL
      AND ret_126 IS NOT NULL
      AND mom_12_1 IS NOT NULL
      AND dist_sma50 IS NOT NULL
      AND dist_sma200 IS NOT NULL
      AND vol_21 IS NOT NULL
      AND vol_126 IS NOT NULL
      AND log_traded_value IS NOT NULL
      AND drawdown_252 IS NOT NULL
      AND log_traded_value > 0
      AND price > 1.0
),

ranked AS (
    -- 6. Within-date percentile rank minus 0.5 over the eligible stocks, as pandas
    --    rank(pct=True, method='average'): ties share their average rank, so
    --    pct = (RANK() + (ties - 1) / 2) / n. PERCENT_RANK() = (RANK() - 1) / (n - 1)
    --    uses another scale and is not used.
    SELECT
        e.*,
        (RANK() OVER (PARTITION BY date ORDER BY ret_21)
            + (COUNT(*) OVER (PARTITION BY date, ret_21) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_ret_21,
        (RANK() OVER (PARTITION BY date ORDER BY ret_63)
            + (COUNT(*) OVER (PARTITION BY date, ret_63) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_ret_63,
        (RANK() OVER (PARTITION BY date ORDER BY ret_126)
            + (COUNT(*) OVER (PARTITION BY date, ret_126) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_ret_126,
        (RANK() OVER (PARTITION BY date ORDER BY mom_12_1)
            + (COUNT(*) OVER (PARTITION BY date, mom_12_1) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_mom_12_1,
        (RANK() OVER (PARTITION BY date ORDER BY dist_sma50)
            + (COUNT(*) OVER (PARTITION BY date, dist_sma50) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_dist_sma50,
        (RANK() OVER (PARTITION BY date ORDER BY dist_sma200)
            + (COUNT(*) OVER (PARTITION BY date, dist_sma200) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_dist_sma200,
        (RANK() OVER (PARTITION BY date ORDER BY vol_21)
            + (COUNT(*) OVER (PARTITION BY date, vol_21) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_vol_21,
        (RANK() OVER (PARTITION BY date ORDER BY vol_126)
            + (COUNT(*) OVER (PARTITION BY date, vol_126) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_vol_126,
        (RANK() OVER (PARTITION BY date ORDER BY log_traded_value)
            + (COUNT(*) OVER (PARTITION BY date, log_traded_value) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_log_traded_value,
        (RANK() OVER (PARTITION BY date ORDER BY drawdown_252)
            + (COUNT(*) OVER (PARTITION BY date, drawdown_252) - 1) / 2.0)
            / COUNT(*) OVER (PARTITION BY date) - 0.5 AS r_drawdown_252
    FROM eligible AS e
),

month_ends AS (
    -- 7. Training and validation use the last calendar date of every month
    SELECT MAX(date) AS date
    FROM calendar
    GROUP BY EXTRACT(YEAR FROM date), EXTRACT(MONTH FROM date)
)

-- 8. Long panel with the binary target: 1 if the close horizon_days own trading days
--    later is at least threshold = 0.1 above the current close, NULL while unknown
SELECT
    r.*,
    (r.date IN (SELECT date FROM month_ends)) AS is_month_end,
    CASE
        WHEN r.fwd IS NULL THEN NULL
        WHEN r.fwd >= 0.1 THEN 1.0
        ELSE 0.0
    END AS y
FROM ranked AS r;
